//! Criterion benchmarks for MinHash insertion performance.
//!
//! Covers cold vs. mature sketches, multiple permutation counts, word widths,
//! and hash families to measure the impact of internal optimizations.
#![allow(missing_docs)]

use core::sync::atomic::Ordering;

use criterion::{criterion_group, criterion_main, BatchSize, BenchmarkId, Criterion};
use minhash_rs::prelude::*;

const ELEMENTS: usize = 10_000;

fn bench_insert_families(c: &mut Criterion) {
    let mut group = c.benchmark_group("insert/families");
    group.sample_size(100);

    for (name, f) in [
        (
            "siphashes13",
            Box::new(|mh: &mut MinHash<u64, 128>, i: u64| {
                mh.insert_with_siphashes13(i);
            }) as Box<dyn Fn(&mut MinHash<u64, 128>, u64)>,
        ),
        (
            "keyed_siphashes13",
            Box::new(|mh: &mut MinHash<u64, 128>, i: u64| {
                mh.insert_with_keyed_siphashes13(i, 0x0123_4567_89AB_CDEF, 0xFEDC_BA98_7654_3210);
            }) as Box<dyn Fn(&mut MinHash<u64, 128>, u64)>,
        ),
        (
            "fnv",
            Box::new(|mh: &mut MinHash<u64, 128>, i: u64| {
                mh.insert_with_fnv(i);
            }) as Box<dyn Fn(&mut MinHash<u64, 128>, u64)>,
        ),
        (
            "keyed_fnv",
            Box::new(|mh: &mut MinHash<u64, 128>, i: u64| {
                mh.insert_with_keyed_fnv(i, 0x0123_4567_89AB_CDEF);
            }) as Box<dyn Fn(&mut MinHash<u64, 128>, u64)>,
        ),
    ] {
        group.bench_function(BenchmarkId::new("cold", name), |b| {
            b.iter_batched(
                MinHash::<u64, 128>::new,
                |mut mh| {
                    for i in 0..ELEMENTS as u64 {
                        f(&mut mh, i);
                    }
                    mh
                },
                BatchSize::PerIteration,
            );
        });
    }

    group.finish();
}

fn bench_insert_mature(c: &mut Criterion) {
    let mut group = c.benchmark_group("insert/mature");
    group.sample_size(100);

    // Pre-populate a sketch so most inserts will not improve any register.
    let mut warm = MinHash::<u64, 128>::new();
    for i in 0..1_000_000u64 {
        warm.insert_with_siphashes13(i);
    }

    for (name, f) in [
        (
            "siphashes13",
            Box::new(|mh: &mut MinHash<u64, 128>, i: u64| {
                mh.insert_with_siphashes13(i);
            }) as Box<dyn Fn(&mut MinHash<u64, 128>, u64)>,
        ),
        (
            "fnv",
            Box::new(|mh: &mut MinHash<u64, 128>, i: u64| {
                mh.insert_with_fnv(i);
            }) as Box<dyn Fn(&mut MinHash<u64, 128>, u64)>,
        ),
    ] {
        group.bench_function(name, |b| {
            b.iter_batched(
                || warm,
                |mut mh| {
                    for i in 0..ELEMENTS as u64 {
                        f(&mut mh, i);
                    }
                    mh
                },
                BatchSize::PerIteration,
            );
        });
    }

    group.finish();
}

fn bench_insert_permutations(c: &mut Criterion) {
    let mut group = c.benchmark_group("insert/permutations");
    group.sample_size(100);

    // u64 with varying permutation counts
    group.bench_function(BenchmarkId::new("u64", 16), |b| {
        b.iter_batched(
            MinHash::<u64, 16>::new,
            |mut mh| {
                for i in 0..ELEMENTS as u64 {
                    mh.insert_with_fnv(i);
                }
                mh
            },
            BatchSize::PerIteration,
        );
    });

    group.bench_function(BenchmarkId::new("u64", 128), |b| {
        b.iter_batched(
            MinHash::<u64, 128>::new,
            |mut mh| {
                for i in 0..ELEMENTS as u64 {
                    mh.insert_with_fnv(i);
                }
                mh
            },
            BatchSize::PerIteration,
        );
    });

    group.bench_function(BenchmarkId::new("u64", 1024), |b| {
        b.iter_batched(
            MinHash::<u64, 1024>::new,
            |mut mh| {
                for i in 0..ELEMENTS as u64 {
                    mh.insert_with_fnv(i);
                }
                mh
            },
            BatchSize::PerIteration,
        );
    });

    group.bench_function(BenchmarkId::new("u64", 8192), |b| {
        b.iter_batched(
            MinHash::<u64, 8192>::new,
            |mut mh| {
                for i in 0..ELEMENTS as u64 {
                    mh.insert_with_fnv(i);
                }
                mh
            },
            BatchSize::PerIteration,
        );
    });

    group.finish();
}

fn bench_insert_word_widths(c: &mut Criterion) {
    let mut group = c.benchmark_group("insert/word_widths");
    group.sample_size(100);

    group.bench_function("u8", |b| {
        b.iter_batched(
            MinHash::<u8, 128>::new,
            |mut mh| {
                for i in 0..ELEMENTS as u64 {
                    mh.insert_with_fnv(i);
                }
                mh
            },
            BatchSize::PerIteration,
        );
    });

    group.bench_function("u16", |b| {
        b.iter_batched(
            MinHash::<u16, 128>::new,
            |mut mh| {
                for i in 0..ELEMENTS as u64 {
                    mh.insert_with_fnv(i);
                }
                mh
            },
            BatchSize::PerIteration,
        );
    });

    group.bench_function("u32", |b| {
        b.iter_batched(
            MinHash::<u32, 128>::new,
            |mut mh| {
                for i in 0..ELEMENTS as u64 {
                    mh.insert_with_fnv(i);
                }
                mh
            },
            BatchSize::PerIteration,
        );
    });

    group.bench_function("u64", |b| {
        b.iter_batched(
            MinHash::<u64, 128>::new,
            |mut mh| {
                for i in 0..ELEMENTS as u64 {
                    mh.insert_with_fnv(i);
                }
                mh
            },
            BatchSize::PerIteration,
        );
    });

    group.finish();
}

fn bench_insert_atomic(c: &mut Criterion) {
    let mut group = c.benchmark_group("insert/atomic");
    group.sample_size(100);

    group.bench_function("fetch_min_fnv", |b| {
        b.iter_batched(
            MinHash::<u64, 128>::new,
            |mut mh| {
                let atomic = mh.as_atomic();
                for i in 0..ELEMENTS as u64 {
                    atomic.fetch_insert_with_fnv(i, Ordering::Relaxed);
                }
                mh
            },
            BatchSize::PerIteration,
        );
    });

    group.finish();
}

criterion_group!(
    benches,
    bench_insert_families,
    bench_insert_mature,
    bench_insert_permutations,
    bench_insert_word_widths,
    bench_insert_atomic,
);
criterion_main!(benches);

//! Insertion benchmarks for the non-atomic MinHash hash families.
#![feature(test)]
extern crate test;

use minhash_rs::prelude::*;

use test::{black_box, Bencher};

const NUMBER_OF_ELEMENTS: usize = 100_000;

#[bench]
fn bench_minhash_insert_with_siphashes13(b: &mut Bencher) {
    b.iter(|| {
        let mut minhash: MinHash<u64, 128> = MinHash::new();
        for i in 0..NUMBER_OF_ELEMENTS {
            minhash.insert_with_siphashes13(black_box(i));
        }
        black_box(minhash)
    });
}

#[bench]
fn bench_minhash_insert_with_keyed_siphashes13(b: &mut Bencher) {
    let key0 = 0x0123_4567_89AB_CDEF;
    let key1 = 0xFEDC_BA98_7654_3210;

    b.iter(|| {
        let mut minhash: MinHash<u64, 128> = MinHash::new();
        for i in 0..NUMBER_OF_ELEMENTS {
            minhash.insert_with_keyed_siphashes13(black_box(i), key0, key1);
        }
        black_box(minhash)
    });
}

#[bench]
fn bench_minhash_insert_with_fnv(b: &mut Bencher) {
    b.iter(|| {
        let mut minhash: MinHash<u64, 128> = MinHash::new();
        for i in 0..NUMBER_OF_ELEMENTS {
            minhash.insert_with_fnv(black_box(i));
        }
        black_box(minhash)
    });
}

#[bench]
fn bench_minhash_insert_with_keyed_fnv(b: &mut Bencher) {
    let key: u64 = 0x0123_4567_89AB_CDEF;

    b.iter(|| {
        let mut minhash: MinHash<u64, 128> = MinHash::new();
        for i in 0..NUMBER_OF_ELEMENTS {
            minhash.insert_with_keyed_fnv(black_box(i), key);
        }
        black_box(minhash)
    });
}

//! Criterion benchmarks comparing sparse and dense MinHash modes.
#![allow(missing_docs)]

use criterion::{criterion_group, criterion_main, BatchSize, BenchmarkId, Criterion};
use minhash_rs::prelude::*;

const SMALL_SET: usize = 100;
const MEDIUM_SET: usize = 1_000;
const LARGE_SET: usize = 50_000;

// ─── Insert: sparse vs dense ────────────────────────────────────────────────

fn bench_insert_sparse_vs_dense(c: &mut Criterion) {
    let mut group = c.benchmark_group("insert/sparse_vs_dense");
    group.sample_size(100);

    for &cardinality in &[SMALL_SET, MEDIUM_SET, LARGE_SET] {
        for &hasher in &["siphashes13", "fnv"] {
            group.bench_function(
                BenchmarkId::new(format!("sparse_{hasher}"), cardinality),
                |b| {
                    b.iter_batched(
                        MinHash::<u64, 128>::sparse,
                        |mut mh| {
                            for i in 0..cardinality as u64 {
                                mh.insert_with_siphashes13(i);
                            }
                            mh
                        },
                        BatchSize::PerIteration,
                    );
                },
            );

            group.bench_function(
                BenchmarkId::new(format!("dense_{hasher}"), cardinality),
                |b| {
                    b.iter_batched(
                        MinHash::<u64, 128>::new,
                        |mut mh| {
                            for i in 0..cardinality as u64 {
                                mh.insert_with_siphashes13(i);
                            }
                            mh
                        },
                        BatchSize::PerIteration,
                    );
                },
            );
        }
    }

    group.finish();
}

// ─── may_contain: sparse vs dense ───────────────────────────────────────────

fn bench_may_contain_sparse_vs_dense(c: &mut Criterion) {
    let mut group = c.benchmark_group("may_contain/sparse_vs_dense");
    group.sample_size(100);

    for &cardinality in &[SMALL_SET, MEDIUM_SET] {
        let sparse: MinHash<u64, 128> =
            (0..cardinality as u64).fold(MinHash::<u64, 128>::sparse(), |mut mh, i| {
                mh.insert_with_siphashes13(i);
                mh
            });
        let dense: MinHash<u64, 128> =
            (0..cardinality as u64).fold(MinHash::<u64, 128>::new(), |mut mh, i| {
                mh.insert_with_siphashes13(i);
                mh
            });

        // Check present values
        group.bench_function(BenchmarkId::new("sparse_present", cardinality), |b| {
            b.iter(|| {
                for i in 0..cardinality as u64 {
                    let _ = sparse.may_contain_value_with_siphashes13(i);
                }
            });
        });

        group.bench_function(BenchmarkId::new("dense_present", cardinality), |b| {
            b.iter(|| {
                for i in 0..cardinality as u64 {
                    let _ = dense.may_contain_value_with_siphashes13(i);
                }
            });
        });

        // Check absent values
        group.bench_function(BenchmarkId::new("sparse_absent", cardinality), |b| {
            b.iter(|| {
                for i in cardinality as u64..(2 * cardinality) as u64 {
                    let _ = sparse.may_contain_value_with_siphashes13(i);
                }
            });
        });

        group.bench_function(BenchmarkId::new("dense_absent", cardinality), |b| {
            b.iter(|| {
                for i in cardinality as u64..(2 * cardinality) as u64 {
                    let _ = dense.may_contain_value_with_siphashes13(i);
                }
            });
        });
    }

    group.finish();
}

// ─── Jaccard: sparse vs dense ───────────────────────────────────────────────

fn bench_jaccard_sparse_vs_dense(c: &mut Criterion) {
    let mut group = c.benchmark_group("jaccard/sparse_vs_dense");
    group.sample_size(100);

    for &cardinality in &[SMALL_SET, MEDIUM_SET] {
        let sparse_a: MinHash<u64, 128> =
            (0..cardinality as u64).fold(MinHash::<u64, 128>::sparse(), |mut mh, i| {
                mh.insert_with_siphashes13(i);
                mh
            });
        let sparse_b: MinHash<u64, 128> = ((cardinality / 2) as u64..(cardinality * 3 / 2) as u64)
            .fold(MinHash::<u64, 128>::sparse(), |mut mh, i| {
                mh.insert_with_siphashes13(i);
                mh
            });

        let dense_a: MinHash<u64, 128> =
            (0..cardinality as u64).fold(MinHash::<u64, 128>::new(), |mut mh, i| {
                mh.insert_with_siphashes13(i);
                mh
            });
        let dense_b: MinHash<u64, 128> = ((cardinality / 2) as u64..(cardinality * 3 / 2) as u64)
            .fold(MinHash::<u64, 128>::new(), |mut mh, i| {
                mh.insert_with_siphashes13(i);
                mh
            });

        group.bench_function(BenchmarkId::new("sparse_vs_sparse", cardinality), |b| {
            b.iter(|| sparse_a.estimate_jaccard_index(&sparse_b));
        });

        group.bench_function(BenchmarkId::new("dense_vs_dense", cardinality), |b| {
            b.iter(|| dense_a.estimate_jaccard_index(&dense_b));
        });

        group.bench_function(BenchmarkId::new("sparse_vs_dense", cardinality), |b| {
            b.iter(|| sparse_a.estimate_jaccard_index(&dense_b));
        });
    }

    group.finish();
}

// ─── Union: sparse vs dense ─────────────────────────────────────────────────

fn bench_union_sparse_vs_dense(c: &mut Criterion) {
    let mut group = c.benchmark_group("union/sparse_vs_dense");
    group.sample_size(100);

    for &cardinality in &[SMALL_SET, MEDIUM_SET] {
        let sparse_a: MinHash<u64, 128> =
            (0..cardinality as u64).fold(MinHash::<u64, 128>::sparse(), |mut mh, i| {
                mh.insert_with_siphashes13(i);
                mh
            });
        let sparse_b: MinHash<u64, 128> = ((cardinality / 2) as u64..(cardinality * 3 / 2) as u64)
            .fold(MinHash::<u64, 128>::sparse(), |mut mh, i| {
                mh.insert_with_siphashes13(i);
                mh
            });

        let dense_a: MinHash<u64, 128> =
            (0..cardinality as u64).fold(MinHash::<u64, 128>::new(), |mut mh, i| {
                mh.insert_with_siphashes13(i);
                mh
            });
        let dense_b: MinHash<u64, 128> = ((cardinality / 2) as u64..(cardinality * 3 / 2) as u64)
            .fold(MinHash::<u64, 128>::new(), |mut mh, i| {
                mh.insert_with_siphashes13(i);
                mh
            });

        group.bench_function(BenchmarkId::new("sparse_vs_sparse", cardinality), |b| {
            b.iter_batched(
                || (sparse_a, sparse_b),
                |(mut a, b)| {
                    a |= &b;
                    a
                },
                BatchSize::PerIteration,
            );
        });

        group.bench_function(BenchmarkId::new("dense_vs_dense", cardinality), |b| {
            b.iter_batched(
                || (dense_a, dense_b),
                |(mut a, b)| {
                    a |= &b;
                    a
                },
                BatchSize::PerIteration,
            );
        });

        group.bench_function(BenchmarkId::new("sparse_vs_dense", cardinality), |b| {
            b.iter_batched(
                || (sparse_a, dense_b),
                |(mut a, b)| {
                    a |= &b;
                    a
                },
                BatchSize::PerIteration,
            );
        });
    }

    group.finish();
}

// ─── Densification cost ─────────────────────────────────────────────────────

fn bench_densification(c: &mut Criterion) {
    let mut group = c.benchmark_group("densification");
    group.sample_size(100);

    // Build a sparse sketch near capacity, then measure auto-densification
    // (triggered by overflow insert)
    let near_capacity: u64 = 127; // PERMUTATIONS - 1 for 128

    group.bench_function("auto_densify_128", |b| {
        b.iter_batched(
            || {
                let mut mh = MinHash::<u64, 128>::sparse();
                for i in 0..near_capacity {
                    mh.insert_with_siphashes13(i);
                }
                mh
            },
            |mut mh| {
                // This insert triggers densification
                mh.insert_with_siphashes13(999_999);
                mh
            },
            BatchSize::PerIteration,
        );
    });

    // Measure densification via equality check (sparse vs dense)
    let sparse: MinHash<u64, 128> =
        (0..MEDIUM_SET as u64).fold(MinHash::<u64, 128>::sparse(), |mut mh, i| {
            mh.insert_with_siphashes13(i);
            mh
        });
    let dense: MinHash<u64, 128> = MinHash::<u64, 128>::new();

    group.bench_function("densify_via_eq", |b| {
        b.iter(|| sparse == dense);
    });

    group.finish();
}

// ─── band_hashes: sparse vs dense ───────────────────────────────────────────

fn bench_band_hashes(c: &mut Criterion) {
    let mut group = c.benchmark_group("band_hashes");
    group.sample_size(100);

    let sparse: MinHash<u64, 128> =
        (0..MEDIUM_SET as u64).fold(MinHash::<u64, 128>::sparse(), |mut mh, i| {
            mh.insert_with_siphashes13(i);
            mh
        });
    let dense: MinHash<u64, 128> =
        (0..MEDIUM_SET as u64).fold(MinHash::<u64, 128>::new(), |mut mh, i| {
            mh.insert_with_siphashes13(i);
            mh
        });

    group.bench_function("sparse", |b| b.iter(|| sparse.band_hashes::<16>()));
    group.bench_function("dense", |b| b.iter(|| dense.band_hashes::<16>()));

    group.finish();
}

// ─── is_empty / is_full ─────────────────────────────────────────────────────

fn bench_state_checks(c: &mut Criterion) {
    let mut group = c.benchmark_group("state_checks");
    group.sample_size(100);

    let sparse_empty = MinHash::<u64, 128>::sparse();
    let dense_empty = MinHash::<u64, 128>::new();

    let sparse_full: MinHash<u64, 128> =
        (0..200_u64).fold(MinHash::<u64, 128>::sparse(), |mut mh, i| {
            mh.insert_with_siphashes13(i);
            mh
        });
    let dense_populated: MinHash<u64, 128> =
        (0..200_u64).fold(MinHash::<u64, 128>::new(), |mut mh, i| {
            mh.insert_with_siphashes13(i);
            mh
        });

    group.bench_function("sparse_is_empty", |b| b.iter(|| sparse_empty.is_empty()));
    group.bench_function("dense_is_empty", |b| b.iter(|| dense_empty.is_empty()));
    group.bench_function("sparse_is_full", |b| b.iter(|| sparse_full.is_full()));
    group.bench_function("dense_is_full", |b| b.iter(|| dense_populated.is_full()));

    group.finish();
}

// ─── FromIterator ───────────────────────────────────────────────────────────

fn bench_from_iter(c: &mut Criterion) {
    let mut group = c.benchmark_group("from_iter");
    group.sample_size(100);

    for &cardinality in &[SMALL_SET, MEDIUM_SET, LARGE_SET] {
        group.bench_function(BenchmarkId::new("collect_dense", cardinality), |b| {
            b.iter_batched(
                || 0..cardinality as u64,
                MinHash::<u64, 128>::from_iter,
                BatchSize::PerIteration,
            );
        });

        group.bench_function(BenchmarkId::new("loop_sparse", cardinality), |b| {
            b.iter_batched(
                || 0..cardinality as u64,
                |range| {
                    range.fold(MinHash::<u64, 128>::sparse(), |mut mh, i| {
                        mh.insert_with_siphashes13(i);
                        mh
                    })
                },
                BatchSize::PerIteration,
            );
        });
    }

    group.finish();
}

criterion_group!(
    benches,
    bench_insert_sparse_vs_dense,
    bench_may_contain_sparse_vs_dense,
    bench_jaccard_sparse_vs_dense,
    bench_union_sparse_vs_dense,
    bench_densification,
    bench_band_hashes,
    bench_state_checks,
    bench_from_iter,
);
criterion_main!(benches);

//! Hash generation and lock-free atomic insertion for MinHash sketches.

use core::hash::{Hash, Hasher};
use core::sync::atomic::Ordering;

use fnv::FnvHasher;
use siphasher::sip128::SipHasher13;

use crate::prelude::{MinHash, Primitive, XorShift};
use crate::splitmix::SplitMix;
/// Generate `count` MinHash word hashes from `value` using the provided `hasher`.
///
/// Used by the [`IterHashes`] trait for external consumers who need the
/// hash stream as an iterator.
///
/// Zero is never emitted. XorShift has zero as a fixed point, so a hash that
/// ever reaches zero would stay zero for the rest of the stream. In particular,
/// when the seed truncates to zero (about one value in 256 for an 8-bit word)
/// the whole stream would collapse to zero and saturate the sketch from a
/// single insertion. Using `saturating_add(1)` keeps the stream non-degenerate
/// for every word width and reserves zero as the sparse mode flag.
fn iter_word_hashes<Word, H, HS>(
    value: H,
    mut hasher: HS,
    count: usize,
) -> impl Iterator<Item = Word>
where
    Word: XorShift + Copy + PartialEq,
    u64: Primitive<Word>,
    H: Hash,
    HS: Hasher,
{
    let zero: Word = 0u64.convert();
    let one: Word = 1u64.convert();

    // Calculate the hash.
    value.hash(&mut hasher);
    let mut hash: Word = hasher.finish().splitmix().splitmix().convert();
    if hash == zero {
        hash = one;
    }

    // Iterate over the words, never emitting the degenerate zero state. The
    // native generators (u8/u16/u32/u64) are bijections on the non-zero space,
    // so once the seed is non-zero they never produce zero; this in-loop guard
    // therefore only fires for widths whose generator truncates a wider type
    // (for example `usize` on a 32-bit target), keeping the stream safe there.
    (0..count).map(move |_| {
        hash = hash.xorshift();
        if hash == zero {
            hash = one;
        }
        hash
    })
}

/// An atomic integer that supports an atomic minimum-update.
pub trait AtomicFetchMin {
    /// The non-atomic word type stored in this atomic.
    type Word;

    /// Set the minimum value atomically
    ///
    /// # Arguments
    /// * `value` - The value to set.
    /// * `ordering` - The ordering to use.
    ///
    fn set_min(&self, value: Self::Word, ordering: Ordering);
}

/// Generates the per-permutation hash streams a MinHash uses for a value.
pub trait IterHashes<Word, const PERMUTATIONS: usize>
where
    Word: XorShift + Copy + PartialEq,
    u64: Primitive<Word>,
{
    /// Iterate on the hashes from the provided value and hasher.
    ///
    /// # Arguments
    /// * `value` - The value to hash.
    fn iter_hashes_from_value<H: Hash, HS: Hasher>(
        value: H,
        hasher: HS,
    ) -> impl Iterator<Item = Word> {
        iter_word_hashes(value, hasher, PERMUTATIONS)
    }

    /// Iterate on the SipHasher13 hashes from the provided value.
    ///
    /// # Arguments
    /// * `value` - The value to hash.
    ///
    /// # Examples
    ///
    /// ```rust
    /// use minhash_rs::prelude::*;
    ///
    /// let mut minhash = MinHash::<u64, 128>::new();
    ///
    /// assert!(!minhash.may_contain_value_with_siphashes13(42));
    /// minhash.insert_with_siphashes13(42);
    /// assert!(minhash.may_contain_value_with_siphashes13(42));
    /// minhash.insert_with_siphashes13(47);
    /// assert!(minhash.may_contain_value_with_siphashes13(47));
    /// ```
    ///
    fn iter_siphashes13_from_value<H: Hash>(value: H) -> impl Iterator<Item = Word> {
        Self::iter_hashes_from_value(value, SipHasher13::new())
    }

    /// Iterate on the keyed SipHasher13 hashes from the provided value.
    ///
    /// # Arguments
    /// * `value` - The value to hash.
    /// * `key0` - The first key.
    /// * `key1` - The second key.
    ///
    /// # Examples
    ///
    /// ```rust
    /// use minhash_rs::prelude::*;
    ///
    /// let mut minhash = MinHash::<u64, 128>::new();
    /// let key0 = 0x0123456789ABCDEF;
    /// let key1 = 0xFEDCBA9876543210;
    ///
    /// assert!(!minhash.may_contain_value_with_keyed_siphashes13(42, key0, key1));
    /// minhash.insert_with_keyed_siphashes13(42, key0, key1);
    /// assert!(minhash.may_contain_value_with_keyed_siphashes13(42, key0, key1));
    /// minhash.insert_with_keyed_siphashes13(47, key0, key1);
    /// assert!(minhash.may_contain_value_with_keyed_siphashes13(47, key0, key1));
    /// ```
    ///
    fn iter_keyed_siphashes13_from_value<H: Hash>(
        value: H,
        key0: u64,
        key1: u64,
    ) -> impl Iterator<Item = Word> {
        Self::iter_hashes_from_value(value, SipHasher13::new_with_keys(key0, key1))
    }

    /// Iterate on the FNV hashes from the provided value.
    ///
    /// # Arguments
    /// * `value` - The value to hash.
    ///
    /// # Examples
    ///
    /// ```rust
    /// use minhash_rs::prelude::*;
    ///
    /// let mut minhash = MinHash::<u64, 128>::new();
    ///
    /// assert!(!minhash.may_contain_value_with_fnv(42));
    /// minhash.insert_with_fnv(42);
    /// assert!(minhash.may_contain_value_with_fnv(42));
    /// minhash.insert_with_fnv(47);
    /// assert!(minhash.may_contain_value_with_fnv(47));
    /// ```
    ///
    fn iter_fnv_from_value<H: Hash>(value: H) -> impl Iterator<Item = Word> {
        Self::iter_hashes_from_value(value, FnvHasher::default())
    }

    /// Iterate on the keyed FNV hashes from the provided value.
    ///
    /// # Arguments
    /// * `value` - The value to hash.
    /// * `key` - The key.
    ///
    /// # Examples
    ///
    /// ```rust
    /// use minhash_rs::prelude::*;
    ///
    /// let mut minhash = MinHash::<u64, 128>::new();
    /// let key = 0x0123456789ABCDEF;
    ///
    /// assert!(!minhash.may_contain_value_with_keyed_fnv(42, key));
    /// minhash.insert_with_keyed_fnv(42, key);
    /// assert!(minhash.may_contain_value_with_keyed_fnv(42, key));
    /// minhash.insert_with_keyed_fnv(47, key);
    /// assert!(minhash.may_contain_value_with_keyed_fnv(47, key));
    /// ```
    fn iter_keyed_fnv_from_value<H: Hash>(value: H, key: u64) -> impl Iterator<Item = Word> {
        Self::iter_hashes_from_value(value, FnvHasher::with_key(key))
    }
}

